with flagged as (select *, case when txn_time - lag(txn_time) over (partition by account_id order by txn_time, id) > interval 14 days then 1 else 0 end as new_group_flag from transactions), sessionized as (select *, sum(new_group_flag) over (partition by account_id order by txn_time, id rows between unbounded preceding and current row) as island_id from flagged) select s.id, s.account_id, s.txn_type, s.amount, s.txn_time, s.merchant, s.is_flagged, s.new_group_flag, s.island_id, (select sum(t2.amount) from transactions t2 where t2.account_id = s.account_id) as sum_transaction_amount from sessionized s
